  "status": "NEEDS_IMPROVEMENT",
  "core_findings": [
    "Electronics has the weakest sampled training separation: 8.85% of negatives outrank positives and 20.72% of margins fall below 0.5. Its embedding alignment score is also highest at 0.6951, indicating greater directional alignment rather than proving collapse.",
    "All four GRU padding audits pass, with unchanged audited candidate ranks. Removing recent context reduces mean margins more than removing older context in every category, although suffix removal also increases the gap to the target."
  ],
  "key_implications": [
    "The measured GRU outputs are consistent across padding and batch execution checks within the declared tolerances.",
    "Electronics shows weaker discrimination than the other categories on sampled training positions; these diagnostics do not establish validation HR@10 performance."
  ],
  "evidence": {
    "headline_metrics": {
      "Electronics:pos_neg_margin_p10": 0.0597,
      "Electronics:pos_neg_neg_beats_pos_rate": 0.0885,
      "Electronics:pos_neg_small_margin_rate": 0.2072,
      "Electronics:embedding_collapse_score": 0.6951
    },
    "brief_metric_read": {
      "Electronics:pos_neg_margin_p10": "Lower-tail training margins are close to zero.",
      "Electronics:embedding_collapse_score": "Highest mean directional alignment among the four categories; not a diversity measure.",
